// The World on 27 November 2026 — make.fun news-image-20261127 entry.
// "Sum up 27 November's world news in one image" ($100 USDC, top-50 share).
// Built by an AI agent in a post-open session on 27 Nov 2026: 13 panels
// generated with real image generation, composed with PIL into a cream
// broadsheet (masthead, big-number strip, 3 heroes, UTC timeline, map).
// Angle: "FIRE IN THE GULF, STORM IN NEW YORK" — Kuwait drone strike,
// Gaza's fraying ceasefire, the storm that stopped the Macy's parade.
// This program writes the entry image to $MAKEFUN_OUTPUT_DIR/entry.png
// (default /output). Node standard library only; no network, no randomness:
// the same bytes come out on every run.
//
// Run: mkdir -p out && MAKEFUN_OUTPUT_DIR=out node main.ts

import { mkdirSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';

// Base64 of entry.png (1024x1024 PNG, rendered by compose.py in the build dir).
const IMAGE_B64 =
  '';

const PNG = Buffer.from(IMAGE_B64, 'base64');
if (PNG.toString('hex', 0, 8) !== '89504e470d0a1a0a') {
  throw new Error('embedded image is not a valid PNG');
}
const width = PNG.readUInt32BE(16);
const height = PNG.readUInt32BE(20);
if (width !== 1024 || height !== 1024) {
  throw new Error(`embedded image must be 1024x1024, got ${width}x${height}`);
}

const outDir = process.env.MAKEFUN_OUTPUT_DIR ?? '/output';
mkdirSync(outDir, { recursive: true });
writeFileSync(join(outDir, 'entry.png'), PNG);
